### Create BufferGeometry from voxel data in Three.js

Source: https://github.com/mrdoob/three.js/blob/dev/manual/pages/voxel-geometry.html

Converts generated voxel data into a Three.js Mesh using BufferAttributes for positions and normals.

```javascript
const {positions, normals, indices} = world.generateGeometryDataForCell(0, 0, 0);
const geometry = new THREE.BufferGeometry();
const material = new THREE.MeshLambertMaterial({color: 'green'});

const positionNumComponents = 3;
const normalNumComponents = 3;
geometry.setAttribute(
    'position',
    new THREE.BufferAttribute(new Float32Array(positions), positionNumComponents));
geometry.setAttribute(
    'normal',
    new THREE.BufferAttribute(new Float32Array(normals), normalNumComponents));
geometry.setIndex(indices);
const mesh = new THREE.Mesh(geometry, material);
scene.add(mesh);
```

--------------------------------

### Clean Scene Meshes and Dispose Resources

Source: https://github.com/mrdoob/three.js/blob/dev/examples/webgl_instancing_performance.html

Removes all meshes from the scene and disposes of their materials and geometries to prevent memory leaks before rebuilding the scene.

```javascript
function clean() {

	const meshes = [];

	scene.traverse( function ( object ) {

		if ( object.isMesh ) meshes.push( object );

	} );

	for ( let i = 0; i < meshes.length; i ++ ) {

		const mesh = meshes[ i ];
		mesh.material.dispose();
		mesh.geometry.dispose();
		scene.remove( mesh );

	}

}
```

--------------------------------

### .dispose()

Source: https://github.com/mrdoob/three.js/blob/dev/docs/pages/BufferGeometry.html.md

Frees GPU-related resources allocated by this BufferGeometry instance. It is crucial to call this method when the geometry is no longer needed to prevent memory leaks.

```APIDOC
## .dispose()

### Description
Frees the GPU-related resources allocated by this instance. Call this method whenever this instance is no longer used in your app.

### Method
dispose

### Fires
- BufferGeometry#event:dispose

### Returns
void
```

--------------------------------

### Three.js WebGL Memory Test Initialization and Animation

Source: https://github.com/mrdoob/three.js/blob/dev/examples/webgl_test_memory.html

Initializes a Three.js scene with a camera and renderer, then continuously creates and disposes of meshes, geometries, textures, and materials to test WebGL memory management.

```javascript
import * as THREE from 'three';
let camera, scene, renderer;
init();
function init() {
  const container = document.createElement( 'div' );
  document.body.appendChild( container );
  camera = new THREE.PerspectiveCamera( 60, window.innerWidth / window.innerHeight, 1, 10000 );
  camera.position.z = 200;
  scene = new THREE.Scene();
  scene.background = new THREE.Color( 0xffffff );
  renderer = new THREE.WebGLRenderer();
  renderer.setPixelRatio( window.devicePixelRatio );
  renderer.setSize( window.innerWidth, window.innerHeight );
  renderer.setAnimationLoop( animate );
  container.appendChild( renderer.domElement );
}
function createImage() {
  const canvas = document.createElement( 'canvas' );
  canvas.width = 256;
  canvas.height = 256;
  const context = canvas.getContext( '2d' );
  context.fillStyle = 'rgb(' + Math.floor( Math.random() * 256 ) + ',' + Math.floor( Math.random() * 256 ) + ',' + Math.floor( Math.random() * 256 ) + ')';
  context.fillRect( 0, 0, 256, 256 );
  return canvas;
}
// function animate() {
  const geometry = new THREE.SphereGeometry( 50, Math.random() * 64, Math.random() * 32 );
  const texture = new THREE.CanvasTexture( createImage() );
  const material = new THREE.MeshBasicMaterial( { map: texture, wireframe: true } );
  const mesh = new THREE.Mesh( geometry, material );
  scene.add( mesh );
  renderer.render( scene, camera );
  scene.remove( mesh );
  // clean up
  geometry.dispose();
  material.dispose();
  texture.dispose();
}
```

### Custom BufferGeometry > Dynamic Updates

Source: https://github.com/mrdoob/three.js/blob/dev/manual/pages/custom-buffergeometry.html

When frequently changing the contents of a BufferAttribute, it is recommended to mark the attribute as dynamic. This serves as a hint to the engine that the data will be updated often. After modifying the attribute's data, the needsUpdate flag must be set to true to ensure the changes are reflected in the next render.

